import{_ as r,c as a,o as e,ag as n}from"./chunks/framework.DfL_BkQ-.js";const m=JSON.parse('{"title":"權限","description":"","frontmatter":{},"headers":[],"relativePath":"zh-TW/guide/permissions.md","filePath":"zh-TW/guide/permissions.md","lastUpdated":1791311600000}'),o={name:"zh-TW/guide/permissions.md"};function d(s,t,l,i,h,p){return e(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="權限" tabindex="-1">權限 <a class="header-anchor" href="#權限" aria-label="Permalink to &quot;權限&quot;">​</a></h1><p>nPlyr 刻意<strong>精簡權限</strong>。因為它是一個媒體播放器（而非剪貼簿或錄影工具），它<strong>不</strong>請求輔助使用或螢幕錄製權限。唯一可能出現的權限，是任何需要網路與檔案的應用程式都需要的那些標準權限。</p><h2 id="網路存取" tabindex="-1">網路存取 <a class="header-anchor" href="#網路存取" aria-label="Permalink to &quot;網路存取&quot;">​</a></h2><p>串流媒體、嗅探與小程式來源都需要出站網路存取。在 macOS 上，App Store 沙盒預設允許——<strong>不會有任何提示</strong>，也無需手動授權。</p><h2 id="檔案與資料夾" tabindex="-1">檔案與資料夾 <a class="header-anchor" href="#檔案與資料夾" aria-label="Permalink to &quot;檔案與資料夾&quot;">​</a></h2><ul><li><strong>開啟本機檔案</strong>使用標準的 macOS 開啟面板，因此由你自己挑選檔案；不需要任何整體資料夾存取權限。</li><li><strong>儲存下載</strong>會寫入你的<strong>下載</strong>資料夾（或你選擇的資料夾）。首次下載時，macOS 可能會彈出沙盒提示以確認位置。授權一次，nPlyr 就會記住該選擇。</li></ul><p>如果之後移動了 nPlyr 的資料或撤銷了存取，你可以在<strong>系統設定 → 隱私與安全性 → 檔案與資料夾</strong>中重新授權。</p><h2 id="通知-選用" tabindex="-1">通知（選用） <a class="header-anchor" href="#通知-選用" aria-label="Permalink to &quot;通知（選用）&quot;">​</a></h2><p>下載完成時，nPlyr 可能會顯示一個本機通知。這是選用的，可在<strong>系統設定 → 通知 → nPlyr</strong> 中關閉。</p><h2 id="nplyr-不請求什麼" tabindex="-1">nPlyr 不請求什麼 <a class="header-anchor" href="#nplyr-不請求什麼" aria-label="Permalink to &quot;nPlyr 不請求什麼&quot;">​</a></h2><table tabindex="0"><thead><tr><th>權限</th><th>是否需要</th><th>原因</th></tr></thead><tbody><tr><td>輔助使用</td><td>否</td><td>鍵盤快捷鍵使用應用程式內事件監視器，而非全域輔助使用控制。</td></tr><tr><td>螢幕錄製</td><td>否</td><td>nPlyr 播放並擷取<em>網路</em>媒體；它從不錄製你的螢幕。</td></tr><tr><td>完全磁碟存取</td><td>否</td><td>所有檔案存取都經由開啟/儲存面板或下載資料夾進行。</td></tr><tr><td>相機 / 麥克風</td><td>否</td><td>nPlyr 是一個觀看工具；它不擷取輸入裝置。</td></tr></tbody></table><p>如果你看到此處未列出的權限提示，幾乎可以肯定來自某個小程式或瀏覽器存取的特定網站——而非核心應用程式。如果看起來有什麼不對，請參閱<a href="/zh-TW/guide/troubleshooting.html">疑難排解</a>。</p>',12)])])}const g=r(o,[["render",d]]);export{m as __pageData,g as default};
